class Solution {
public:
    int snakesAndLadders(vector<vector<int>>& board) {
        int n = board.size();
        vector<int> dest(n * n + 1);
        int sq = 1;
        for (int r = n - 1, k = 0; r >= 0; r--, k++) {
            for (int c = 0; c < n; c++) {
                int col = k % 2 == 0 ? c : n - 1 - c;
                int to = board[r][col] == -1 ? sq : board[r][col];
                dest[sq] = to;
                sq++;
            }
        }
        vector<bool> seen(n * n + 1, false);
        queue<int> q;
        q.push(1);
        seen[1] = true;
        int rolls = 0;
        while (!q.empty()) {
            int sz = q.size();
            for (int s = 0; s < sz; s++) {
                int cur = q.front();
                q.pop();
                if (cur == n * n) return rolls;
                for (int d = 1; d <= 6 && cur + d <= n * n; d++) {
                    int nxt = dest[cur + d];
                    if (!seen[nxt]) {
                        seen[nxt] = true;
                        q.push(nxt);
                    }
                }
            }
            rolls++;
        }
        return -1;
    }
};
